import{_ as e,o as n,c as o,ak as r}from"./chunks/framework.BQBmvEkd.js";const i="/projects/WonderEcho/en/latest/assets/image3.CM-cw1DK.webp",a="/projects/WonderEcho/en/latest/assets/image4.zTGUdv2X.webp",m=JSON.parse('{"title":"1. Module Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1_Module_Introduction.md","filePath":"docs/1_Module_Introduction.md"}'),s={name:"docs/1_Module_Introduction.md"};function d(c,t,l,h,u,p){return n(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_1-module-introduction" tabindex="-1">1. Module Introduction <a class="header-anchor" href="#_1-module-introduction" aria-label="Permalink to &quot;1. Module Introduction&quot;">​</a></h1><h2 id="_1-1-introduction" tabindex="-1">1.1 Introduction <a class="header-anchor" href="#_1-1-introduction" aria-label="Permalink to &quot;1.1 Introduction&quot;">​</a></h2><p>The WonderEcho is an all-in-one voice interaction module built on the CI1302 chip, designed for speech recognition and playback. It supports offline neural network (NN) acceleration and hardware-accelerated voice signal processing, leveraging advanced noise reduction and neural network models to deliver highly accurate recognition results.</p><p>The CI1302 chip features a Brain Neural Processing Unit (BNPU), supporting offline NN acceleration and hardware-accelerated speech processing. With a CPU clock speed of up to 220 MHz, it enables far-field voice recognition in offline mode. Additionally, it has 2MB of built-in flash storage, capable of recognizing up to 300 command words.</p><p>Thanks to its user-friendly operation and outstanding speech recognition performance, the WonderEcho module is ideal for a wide range of applications, including smart home systems, conversational robots, educational robots, and in-vehicle dispatch terminals.</p><h2 id="_1-2-working-principle" tabindex="-1">1.2 Working Principle <a class="header-anchor" href="#_1-2-working-principle" aria-label="Permalink to &quot;1.2 Working Principle&quot;">​</a></h2><p>This module operates in wake word activation mode, requiring users to say a designated wake word to activate the voice interaction module before issuing commands. The default wake word is <strong>&quot;Hello Hiwonder&quot;</strong>. If no voice input is detected within 15 seconds, the module will enter sleep mode and must be reactivated before further use.</p><p>Once the CI1302 chip recognizes a voice command, it transmits the corresponding instruction to the IIC chip, which then processes and broadcasts the response. The IIC chip stores the received command and transmits it using the IIC slave protocol.</p><p>This module supports customization of both wake words and command words. For instructions on modifying them, please refer to <a href="https://wiki.hiwonder.com/projects/WonderEcho/en/latest/docs/3_Modify_Wake_up_and_Command_Words.html" target="_blank" rel="noreferrer">3. Modifying Wake Words and Command Words</a>.</p><h2 id="_1-3-notice" tabindex="-1">1.3 Notice <a class="header-anchor" href="#_1-3-notice" aria-label="Permalink to &quot;1.3 Notice&quot;">​</a></h2><p>(1) Ensure the module is powered with 5V to prevent damage.</p><p>(2) Keep the surroundings quiet, as background noise may affect recognition accuracy.</p><p>(3) Speak loudly and clearly at a moderate pace. Maintain a distance of approximately 5 meters from the module for optimal performance.</p><h2 id="_1-4-port-instruction" tabindex="-1">1.4 Port Instruction <a class="header-anchor" href="#_1-4-port-instruction" aria-label="Permalink to &quot;1.4 Port Instruction&quot;">​</a></h2><img loading="lazy" height="618" width="800" src="'+i+'" class="common_img" style="width:650px;"><img loading="lazy" height="576" width="917" src="'+a+'" class="common_img" style="width:650px;"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>No.</strong></th><th style="text-align:center;"><strong>Hardware name</strong></th><th style="text-align:center;"><strong>Instruction</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">Speaker</td><td style="text-align:center;">Convert the analog signal into sound</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">Microphone</td><td style="text-align:center;">Convert the sound into analog signal</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">RST button</td><td style="text-align:center;">Reset button</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">Blue signal indicator</td><td style="text-align:center;">Signal indicator remains on continuously, and it will blink once while a keyword is detected</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">Red power indicator</td><td style="text-align:center;">It remains on when the power supply is normal</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">I2C port</td><td style="text-align:center;">Serve as an I2C slave device, providing power and facilitating communication with the master device</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:center;">Type-C port</td><td style="text-align:center;">For power supply and firmware update for the CI1302 chip.</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:center;">CI1302 chip</td><td style="text-align:center;">A high-performance voice recognition chip. It recognizes voice and outputs corresponding signals</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:center;">I2C chip</td><td style="text-align:center;">Transform the commands from the voice recognition chip into commands of the I2C protocol</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:center;">Amplifier chip</td><td style="text-align:center;">Convert digital signals into analog signals to drive the speaker</td></tr></tbody></table><h2 id="_1-5-test-instruction" tabindex="-1">1.5 Test Instruction <a class="header-anchor" href="#_1-5-test-instruction" aria-label="Permalink to &quot;1.5 Test Instruction&quot;">​</a></h2><p>(1) Connect the WonderEcho module to your PC using a Type-C data cable.</p><p>(2) Activate the module by saying the wake-up word <strong>&quot;Hello Hiwonder&quot;</strong>.</p><p>(3) Test the module by speaking one of the command words: <strong>&quot;go straight&quot;</strong>, <strong>&quot;go backward&quot;</strong>, <strong>&quot;turn left&quot;</strong>, or <strong>&quot;turn right&quot;</strong>.</p><p>(4) If no voice input is detected within 15 seconds, the module will enter sleep mode and must be reactivated before further use.</p>',22)])])}const f=e(s,[["render",d]]);export{m as __pageData,f as default};
